// Own held-right fields; since uses existing RFC3339 time representation.
// Native Hold also carries Seen. The live
// [Lease](https://openabstractions.github.io/reference.html#concept-rights.lease)
// is connection-owned and cannot be recreated from these fields.
type HoldMetadata struct {
	App   string
	Name  string
	Right string
	Why   string
	Since string
}

// Deprecated native token-service response descriptor. Removal is scheduled for
// Train B (expected 0.9.0), W2-01a.1, under TD13/TD57's stored-state and
// declared outside-adopter retirement conditions. Own response fields are
// projected without native Seen evidence. Any nonempty code/error is refusal,
// including unknown codes. This is a common descriptor, not a replacement
// legacy Response codec or generated service client.
type ResponseMetadata struct {
	Code    string
	Error   string
	Secret  string
	Token   string
	Expires string
	App     *AppMetadata
	Right   string
	Apps    []AppMetadata
	Holds   []HoldMetadata
}

// [Subject](https://openabstractions.github.io/reference.html#concept-rights.subject):
// Receiving policy account and program target. Native programs use the shared
// absolute-path/MSIX grammar; the distinct remote kind is remote:<64 lowercase
// hex leaf-SPKI-SHA256> from the shared live-pin mapping. Remote targets match
// exact account/token/action/resource only, with no defaults, wildcard
// selectors or native operator authority. This serialized subject is an
// assertion by an explicitly authorized native enforcement point, contains no
// proof and cannot authorize its own use. Direct decisions derive native
// receiving
// [Program](https://openabstractions.github.io/reference.html#concept-identity.listener-program-need)
// evidence. Authority setters and actors remain native.
type Subject struct {
	Account string
	Program string
}

// A point-in-time policy decision. Only permitted allows an enforcement point
// to proceed. denied is an explicit exact deny; not_granted has no unexpired
// exact rule; unknown_action is outside the current catalogue. Evaluated
// permitted/denied/not_granted/unknown_action decisions carry an opaque
// revision observed with that decision. Errors carry none. No lease, token,
// cached permission lifetime or human consent is conveyed.
type Decision struct {
	Outcome        DecisionOutcome
	PolicyRevision string
}

// A decision and bounded opaque freshness observation from the same state read.
// Evaluated decisions carry observed_revision. Refusals carry none. This
// observation conveys no permission lifetime.
type RevisionDecision struct {
	Decision         Decision
	ObservedRevision string
}

// The one refusal record every OA service carries beside a refusing outcome
// (RIGHTS-E3; conventions CONV-E4). source names the authority that refused:
// rights, credentials, license, terms, identity or os. decision is denied for
// an explicit refusal, not_granted where no rule permits, and person_only where
// only the person may answer the question. ask says whether asking can change
// the answer: available, or none. action is the exact registered
// <owner>/<name>; question the pending question's id; credential the
// credential's name; retry_after_ms the earliest useful retry in milliseconds,
// omitted when zero. Stop asking is denied with ask none. Current carriers
// include config@2, messages@1, registry@3, endpoint@2 and chat@3, declared in
// config.thrift, messages.thrift, registration.thrift and inference.thrift.
// Other services adopt it in their scheduled versions.
type RefusalDetail struct {
	Source       RefusalSource
	Decision     RefusalDecision
	Ask          RefusalAsk
	Action       string
	Question     string
	Credential   string
	RetryAfterMs int64
}

// One exact policy rule. Subject is the administrative target, never caller
// proof. Account is 1..128 UTF-8 bytes; program is a normalized absolute path
// up to 4096 bytes; action is 1..128 bytes and belongs to the current
// catalogue; resource is 1..1024 bytes. All strings exclude control characters.
// permit=false is an explicit deny; revocation removes the exact rule and
// restores not_granted.
type PolicyRule struct {
	Subject  Subject
	Action   string
	Resource string
	Permit   bool
}

// Latest-policy enumeration: 1..64 requested rules and at most 256 KiB encoded
// reply, including catalogue, cursor and indentation. Catalogue is the
// configured seed plus registered actions, sorted, bounded to 64 actions of 128
// bytes. Rules are every retained rule, including expired rules the next write
// removes; ReadRule reports expiry and provenance. Page carries the exact
// durable content revision. A noncomplete page has a nonempty next cursor.
// Refusals have empty revision/catalog/rules/next and complete=false. Cursors
// are at most 256 UTF-8 bytes, bind receiving account/program and host
// epoch/revision, and return gap after change/restart/scope mismatch. Restart
// from empty cursor. No immutable multipage snapshot or historical change
// replay is promised.
type PolicyPage struct {
	Outcome  PolicyPageOutcome
	Revision string
	Catalog  []string
	Rules    []PolicyRule
	Next     string
	Complete bool
}

// Read-only policy invalidation. changed carries a new nonempty opaque cursor
// and current durable revision; an empty after requests this snapshot.
// unchanged carries the confirmed after cursor and current revision. Expiry
// changes the observation cursor while durable revision stays unchanged;
// ReadRule confirms expiry. gap carries after and empty revision: restart from
// empty after. invalid/forbidden/unavailable carry empty next/revision. Cursors
// bind receiving Program, host epoch and expiry-sensitive state, never
// enumerate rules or grant a permission lease. native declares policy-owner
// commit callbacks plus expiry deadlines. At most 256 cursor bytes and 128
// revision bytes; no rule contents, replay or second policy store.
type PolicyObservation struct {
	Outcome   PolicyObservationOutcome
	Next      string
	Revision  string
	Mechanism PolicyObservationMechanism
}

// Applied/conflict carry the revision and optional exact current rule observed
// inside the conditional edit; absent current means no exact rule. Other
// outcomes carry no revision/current. A stale expected revision always
// conflicts, including when the desired state happens to match. No-op edits at
// the matching revision preserve it without writing. A lost reply is uncertain:
// retrying the same expected revision cannot overwrite a later edit, and may
// conflict after a successful original change. Reconcile the returned current
// state or fresh history before choosing another edit. This is optimistic
// concurrency, not an exactly-once mutation journal.
type PolicyEdit struct {
	Outcome  PolicyEditOutcome
	Revision string
	Current  *PolicyRule
}

// One exact rule with its provenance. set_by is the subject the rights service
// established for the party that set the rule: the operator's receiving Program
// evidence, or the service's own account and executable for native edits. The
// request never supplies it. set_at is the service's UTC edit time as RFC 3339
// with milliseconds. why is the operator's reason of 0..256 UTF-8 bytes without
// control characters. expires is empty for a rule without expiry, or the UTC
// instant, in the same format, from which the rule decides nothing.
type RuleRecord struct {
	Rule    PolicyRule
	SetBy   Subject
	SetAt   string
	Why     string
	Expires string
}

// found and expired carry the revision and the exact record. expired names a
// retained rule at or past its expiry; it decides nothing and the next policy
// write removes it. unknown carries the revision and no record. invalid,
// forbidden and unavailable carry neither.
type RuleRead struct {
	Outcome  RuleReadOutcome
	Revision string
	Record   *RuleRecord
}

// One registered catalogue action. Seeded actions have no entry. registered_by
// is the subject the rights service established for the registering party: the
// operator's receiving Program evidence, or the service's own account and
// executable for native registration. registered_at is the service's UTC time
// as RFC 3339 with milliseconds.
type CatalogEntry struct {
	Action       string
	RegisteredBy Subject
	RegisteredAt string
}

// Operator-declared description of a stable app feature. feature_app names the
// described app, never the grant/decision subject. app_label and description
// are trimmed control-free UTF-8 text of 1..128 and 1..512 bytes. declared_risk
// is trimmed 1..32 bytes of display metadata: routine, sensitive,
// administrative and unknown align existing words; unfamiliar words have
// unknown interpretation. Risk text changes no authorization, question tier or
// answerer authority. Metadata establishes no code behavior or vendor trust.
type ActionDescription struct {
	Action       string
	FeatureApp   Subject
	AppLabel     string
	Description  string
	DeclaredRisk string
}

// Service-owned definition metadata for one stable exact action. Operations
// identify owning IDL methods and existing domain effects. resource_profile is
// an immutable namespaced profile@version bound to a compiled owning validator
// by trusted composition; unknown profiles/versions are refused. Legacy
// exact-string profiles retain bounded exact bytes, including literal '*', and
// describe their resource owner's existing validation. served distinguishes
// implemented receiving enforcement from defined/unserved operations; unserved
// definitions admit no first-use request. first_use names only existing exact
// or consuming paired admission; dynamic tier/answerer facts remain separately
// service-owned. Disclosure and lifecycle explain data/effects and account,
// deletion and name-reuse boundaries. Metadata conveys no proof, grant,
// callback or scope selector. Changed authority requires a new action
// identity/version. This additive record is available to generated consumers;
// no service method publishes or registers definitions in this slice.
type PermissionDefinition struct {
	Action          string
	OwnerContract   string
	Operations      []string
	ResourceProfile string
	ResourceType    string
	EnforcedBy      []string
	Disclosure      string
	Lifecycle       string
	FirstUse        PermissionFirstUse
	Served          bool
}

// One current catalogue action. choices is exactly allow, block, remove_rule,
// naming existing SetRule permit/deny and RevokeRule choices without authority
// to invoke them. Description and publication fields occur together or are all
// absent. description.action equals action. published_by is the operator
// subject established for publication; feature_app is its administrative
// declaration, and the imported descriptor's author/vendor remain unverified.
// published_at is service UTC RFC 3339 with milliseconds. Undescribed names
// carry no invented app information.
type DescribedAction struct {
	Action      string
	Choices     []string
	Description *ActionDescription
	PublishedBy *Subject
	PublishedAt string
}

// applied, conflict and unknown carry the revision observed inside the
// conditional edit. applied and conflict carry the action's registration entry
// when one exists; a seeded or retired action has none. unknown means
// RetireAction named an action outside the catalogue. exhausted means the
// catalogue already holds 64 actions. invalid, exhausted, forbidden and
// unavailable carry no revision or entry. A stale expected revision always
// conflicts.
type ActionEdit struct {
	Outcome  ActionEditOutcome
	Revision string
	Current  *CatalogEntry
}

// applied/conflict carry the revision and current described catalogue action
// when present; all other outcomes carry neither. A stale expected revision
// always conflicts. Identical metadata at the current revision is a no-op. A
// valid correction changes descriptor publication provenance/time and revision,
// preserving all grants, denies, targets, expiry and private answer receipts.
// Registration alone grants nothing.
type DescriptionEdit struct {
	Outcome  ActionEditOutcome
	Revision string
	Current  *DescribedAction
}

// Sorted current catalogue descriptions, including undescribed names, under one
// durable revision. 1..64 requested entries and at most 256 KiB encoded reply.
// Noncomplete pages have a nonempty next cursor and at least one entry; cursors
// are at most 256 UTF-8 bytes. Refusals have empty revision/actions/next and
// complete=false. No retained enumeration snapshot or historical replay.
type DescriptionPage struct {
	Outcome  PolicyPageOutcome
	Revision string
	Actions  []DescribedAction
	Next     string
	Complete bool
}

// One account-wide default the receiving runtime configures: a permit on action
// for every program of the runtime's own account that has no live rule of its
// own on the queried target. name is 1..64 bytes of lowercase ASCII letters,
// digits, '.', '_' and '-'. resource is the one exact resource the default
// covers; with every_resource it is empty and the default covers every resource
// of the action. on is the switch: true after a fresh install, until an
// operator turns it off. set_by and set_at occur together, name the operator
// subject the rights service established for the last switch edit and its
// service UTC time, and are absent while the switch was never turned. A
// per-program rule, a Block included, decides before any default; a configured
// excluded program, such as a script host, and every other account receive no
// default. A default writes no rule.
type AccountDefault struct {
	Name          string
	Action        string
	Resource      string
	EveryResource bool
	On            bool
	SetBy         *Subject
	SetAt         string
}

// Every configured account-wide default, sorted by name, under one durable
// revision; at most 32 entries. Refusals have an empty revision and no
// defaults.
type DefaultPage struct {
	Outcome  PolicyPageOutcome
	Revision string
	Defaults []AccountDefault
}

// applied and conflict carry the revision and the named default's current state
// observed inside the conditional edit. Other outcomes carry neither. A stale
// expected revision always conflicts. Setting a switch to its current state at
// the matching revision is a no-op that keeps the revision.
type DefaultEdit struct {
	Outcome  PolicyEditOutcome
	Revision string
	Current  *AccountDefault
}

// One exact decision for a subject with the step that decided it, from the same
// evaluation a decision makes. own_rule is the subject's own live exact rule,
// matched by program identity; typed_block a live typed Block that covers the
// target; account_default the named account-wide default that permits;
// default_excluded a named default switched on for the target that the
// configured exclusion, such as the script-host rule, keeps from this program;
// none no rule and no default. outcome and policy_revision are those the
// decision carries. Refusals (invalid, forbidden, unavailable) carry no
// revision, source or name.
type DecisionExplanation struct {
	Outcome        DecisionOutcome
	PolicyRevision string
	Source         *DecisionSource
	DefaultName    string
}

type PermissionKey struct {
	Action          string
	ResourceProfile string
}

// One has one bounded canonical owning-IDL document. All omits target and
// selects the fixed profile collection within the rule subject's
// account/runtime. Operator inputs are prepared by the trusted owning profile;
// arbitrary captured identity evidence is refused.
type ResourceSelector struct {
	Kind   ResourceSelectorKind
	Target []byte
}

type PermissionSelection struct {
	Permission PermissionKey
	Selector   ResourceSelector
}

// A concrete resource, never a grant selector. Historical captured evidence is
// accepted only from an explicitly authorized receiving enforcer; no direct
// caller obtains effect authority from this assertion.
type ConcreteResource struct {
	Permission PermissionKey
	Target     []byte
}

type CheckBatchRequest struct {
	ExpectedRevision    string
	CollectionAdmission *PermissionKey
	Resources           []ConcreteResource
}

// checked has one revision and ordered evaluated outcomes from one immutable
// policy snapshot and one clock sample. conflict has the observed revision and
// no outcomes. Other refusals have empty revision and no outcomes. A batch
// never mixes revisions or partially succeeds. No authority lease is issued.
type BatchDecision struct {
	Outcome           BatchCheckOutcome
	Revision          string
	CollectionOutcome *DecisionOutcome
	Outcomes          []DecisionOutcome
}

// Full key is definition.action plus definition.resource_profile. Service-owned
// collection/all_effect state membership and present/future meaning. Only
// actually served receiving selectors are advertised. Existing
// PermissionDefinition.first_use remains the legacy projection; new selector
// first use uses first_use_selectors.
type SelectorPermissionDefinition struct {
	Definition         PermissionDefinition
	Label              string
	SupportedSelectors []ResourceSelectorKind
	FirstUseSelectors  []ResourceSelectorKind
	Collection         string
	AllEffect          string
	RequestType        string
}

type PermissionDefinitionPage struct {
	Outcome     PolicyPageOutcome
	Revision    string
	Definitions []SelectorPermissionDefinition
	Next        string
	Complete    bool
}

// Immutable finite expansion identified by namespaced bundle@version and
// deterministic content digest. This slice permits only member profiles with
// the same owning target document and collection. Each member validates
// independently. No mapping language, live role reference, future operation or
// permission-administration effect is implied.
type PermissionBundleDefinition struct {
	BundleRef          string
	OwnerContract      string
	Label              string
	TargetType         string
	SupportedSelectors []ResourceSelectorKind
	Members            []PermissionKey
	Disclosure         string
	DefinitionDigest   string
}

type PermissionBundlePage struct {
	Outcome  PolicyPageOutcome
	Revision string
	Bundles  []PermissionBundleDefinition
	Next     string
	Complete bool
}

// The exact original finite expansion, retained independently of later
// catalogue changes. All selected member profiles must accept the same
// canonical target/collection. A new version requires new consent.
type BundleExpansion struct {
	BundleRef        string
	DefinitionDigest string
	Selector         ResourceSelector
	Selections       []PermissionSelection
}

// Complete typed permit proposal retained by a trusted Asks admission owner.
// When bundle is present its selections equal this complete list. Native
// preparation establishes subject and target evidence. Text, a serialized
// subject or an app-supplied effect grants no authority.
type PermissionEffect struct {
	Subject    Subject
	Selections []PermissionSelection
	Bundle     *BundleExpansion
}

type SelectorRule struct {
	Subject   Subject
	Selection PermissionSelection
	Permit    bool
}

// Rights-established historical application identity and immutable expansion.
// An origin explains how rules arose; it does not assert that all original
// members remain current.
type BundleOrigin struct {
	ID        string
	Expansion BundleExpansion
}

type SelectorRuleRecord struct {
	Rule         SelectorRule
	SetBy        Subject
	SetAt        string
	Why          string
	Expires      string
	BundleOrigin *BundleOrigin
}

type SelectorRulePage struct {
	Outcome  PolicyPageOutcome
	Revision string
	Records  []SelectorRuleRecord
	Next     string
	Complete bool
}

type SelectorRuleRead struct {
	Outcome  RuleReadOutcome
	Revision string
	Record   *SelectorRuleRecord
}

// Applied/conflict carry the locked observed revision and complete bounded
// affected state. Stale expected revision always conflicts, including matching
// desired state. Other refusals carry empty revision/current. Atomic edits have
// no per-member success. Individual replacement removes that row's active
// bundle origin; remaining rows keep historical origin.
type SelectorEdit struct {
	Outcome      PolicyEditOutcome
	Revision     string
	Current      []SelectorRuleRecord
	BundleOrigin *BundleOrigin
}

// Old exact authority plus an optional receiver-known concrete effect. Trusted
// compiled capability equivalence validates the supplied effect against this
// old operation and its fixed collection. Original legacy authority and live
// equivalent typed restrictions are evaluated at one snapshot. Missing concrete
// detail on a coarse view uses conservative collection intersection. This
// method imports explicit blocks only; it grants no typed permit.
type LegacyOperationRequest struct {
	LegacyAction      string
	LegacyResource    string
	ConcreteOperation *ConcreteResource
}

// The one refusal record every OA service carries beside a refusing outcome
// (RIGHTS-E3; conventions CONV-E4). source names the authority that refused:
// rights, credentials, license, terms, identity or os. decision is denied for
// an explicit refusal, not_granted where no rule permits, and person_only where
// only the person may answer the question. ask says whether asking can change
// the answer: available, or none. action is the exact registered
// <owner>/<name>; question the pending question's id; credential the
// credential's name; retry_after_ms the earliest useful retry in milliseconds,
// omitted when zero. Stop asking is denied with ask none. Current carriers
// include config@2, messages@1, registry@3, endpoint@2 and chat@3, declared in
// config.thrift, messages.thrift, registration.thrift and inference.thrift.
// Other services adopt it in their scheduled versions.
type EndpointRefusalDetail struct {
	Source       EndpointRefusalSource
	Decision     EndpointRefusalDecision
	Ask          EndpointRefusalAsk
	Action       string
	Question     string
	Credential   string
	RetryAfterMs int64
}

// Producer assertion validated by the runtime. Kind is the governed open
// build-time vocabulary <owner>/<name>, not a display string or an authority
// claim. copy identifies one copy within the kind. reason follows D87
// domain:word:detail as open display text. checked is the producer's claimed
// check time. Custom/unknown copies are unverified; readiness remains
// independent. No runtime kind-registration method is introduced.
type EndpointProducerCheck struct {
	Kind    string
	Copy    string
	State   EndpointProducerCheckState
	Reason  string
	Checked string
}

// endpoint@2 service observation. definition_hash is sha256: plus64 lowercase
// hex over this service version's canonical wire form (CONV-V2), verified by
// the definition-hash owner. reason retains readiness errors and is empty when
// ready. capabilities remain display-only. Program-level producer checks belong
// to EndpointDescription and are independent of service readiness.
type EndpointServiceState struct {
	Service        string
	Readiness      EndpointServiceReadiness
	Reason         string
	Guarantees     []string
	Capabilities   map[string]string
	DefinitionHash string
}

// Complete endpoint@2 description with each advertised service's definition
// hash and one program-level producer-check list. Checks are independent of
// service readiness; absence means unobserved, never verified.
// Forbidden/unavailable authority refusals carry the single Rights-owned
// EndpointRefusalDetail; other outcomes omit it. Unsupported carries the
// existing bounded reason with D87 unsupported:not_implemented words; no closed
// staged-reason vocabulary is frozen. Non-described replies disclose no
// program/version/services/checks. Endpoint@1 and its closed
// EndpointDescription/EndpointServiceState remain unchanged. The compact value
// ceiling excluding insignificant JSON whitespace is IPC-F1; an oversized whole
// reply is unavailable/bound:reply_bytes without truncation.
type EndpointDescription struct {
	Outcome  EndpointDescriptionOutcome
	Program  string
	Version  string
	Services []EndpointServiceState
	Refusal  *EndpointRefusalDetail
	Reason   string
	Checks   []EndpointProducerCheck
}

type EndpointDescriptionResult struct {
	Value EndpointDescription
}

